2 7 8 3 9 [0 1 4 5 6]
40 = 1(4!) + 16
2 7 8 3 9 1 [0 4 5 6]
16 = 2(3!) + 4
2 7 8 3 9 1 5 [0 4 6]
4 = 1(2!) + 2 <-- we don't write 4 = 2(2!) + 0 here; we need 0<r<=2!
2 7 8 3 9 1 5 4 [0 6]
2 = 1(1!) + 1
2 7 8 3 9 1 5 4 6 [0]

